    "If 'Include only rebilled transactions' is turned on: Cost includes charges to agency against only rebilled usage. If 'Include only rebilled transactions' is turned off: Cost includes charges to agency against all usage.": "Je-li zapnuto „Zahrnout pouze přefakturované transakce“: náklady zahrnují poplatky agentuře pouze za přefakturované využití. Je-li vypnuto: náklady zahrnují poplatky agentuře za veškeré využití.",
    "If 'Include only rebilled transactions' is turned on: Total cost to your agency against all rebilled usage. If 'Include only rebilled transactions' is turned off: Total cost to your agency against all usage.": "Je-li zapnuto „Zahrnout pouze přefakturované transakce“: celkové náklady vaší agentury za veškeré přefakturované využití. Je-li vypnuto: celkové náklady vaší agentury za veškeré využití.",
