    "• All new incoming reviews will be automatically detected if they are spam or not.": "• U všech nových příchozích recenzí se automaticky vyhodnotí, zda jde o spam.",
    "• Users will have control to override the decision taken by the system.": "• Uživatelé budou moci rozhodnutí systému přepsat.",
    "• Automatic Reviews Reply will not be sent for spam detected reviews.": "• Na recenze označené jako spam se automatická odpověď neodešle.",
    "• Scheduled Review Replies can be stopped by manually marking reviews as spam.": "• Naplánované odpovědi lze zastavit ručním označením recenze jako spam.",
    "• Spam detected reviews will not show up in Review Widget.": "• Recenze označené jako spam se nezobrazí ve widgetu recenzí.",
    "• Spam detected reviews will be not added in Overview Dashboard.": "• Recenze označené jako spam se nezapočítají do přehledové nástěnky.",
